 {modal==='card'&&<><SelectField label="Изделие" value={form.product_id} set={v=>set('product_id',v)} options={lookups.products?.map(p=>[String(p.id),p.product_code+' — '+p.product_name])||[]}/><div className="section"><div><h3>Лист обмера · размеры по КД</h3><p>Добавляйте строки и установки. Отклонения вводятся отдельно и отображаются сверху и снизу размера, как на чертеже.</p></div><div className="tableActions"><button type="button" className="secondary" onClick={addCardInstallation}>Добавить установку</button></div></div>{[...new Set((form.parameters||[]).map(p=>Number(p.installation_no)||1))].sort((a,b)=>a-b).map(installation=><section className="measurementInstall" key={installation}><div className="installHeading"><b>Установка {installation}</b><button type="button" className="secondary smallButton" onClick={()=>addCardParameter(installation)}>Добавить размер</button></div><div className="tableWrap"><table className="measurementBuilder"><thead><tr><th>№</th><th>Знак</th><th>Размер по КД</th><th>Верхнее отклонение</th><th>Нижнее отклонение</th><th></th></tr></thead><tbody>{(form.parameters||[]).map((p,i)=>({p,i})).filter(x=>Number(x.p.installation_no)===installation).map(({p,i},rowIndex)=><tr key={i}><td>{rowIndex+1}</td><td><select className="inlineField symbolSelect" aria-label="Знак размера" value={p.dimension_prefix||''} onChange={e=>setCardParameter(i,'dimension_prefix',e.target.value)}><option value="">—</option><option value="Ø">Ø</option><option value="М">М</option></select></td><td><input className="inlineField dimensionInput" aria-label="Размер по КД" placeholder="28,7 / 30×1-6g / 0,6×45°" value={p.drawing_dimension||''} onChange={e=>setCardParameter(i,'drawing_dimension',e.target.value)} required/></td><td><input className="inlineField" aria-label="Верхнее отклонение" placeholder="+0,21" value={p.upper_deviation||''} onChange={e=>setCardParameter(i,'upper_deviation',e.target.value)}/></td><td><input className="inlineField" aria-label="Нижнее отклонение" placeholder="−0,21" value={p.lower_deviation||''} onChange={e=>setCardParameter(i,'lower_deviation',e.target.value)}/></td><td><button type="button" className="secondary smallButton" onClick={()=>setForm(f=>({...f,parameters:f.parameters.filter((_,n)=>n!==i)}))}>Удалить</button></td></tr>)}</tbody></table></div></section>)}<div className="formHint">Например, для размера Ø28,7 с допусками +0,21 / −0,21 введите основной размер в первую графу, верхнее отклонение во вторую, нижнее — в третью. Резьбу, фаску или диапазон вводите целиком в графу «Размер по КД», а отклонения оставляйте пустыми.</div></>}
 {modal==='output'&&<><Field label="Дополнительное количество деталей (если осталось)" type="number" min={0} value={form.quantity} set={v=>set('quantity',v)} required/><Field label="Примечание" value={form.note} set={v=>set('note',v)}/><label className="formField" style={{display:"flex",alignItems:"center",gap:10}}><input type="checkbox" checked={form.finish===true} onChange={e=>set("finish",e.target.checked)}/>Итоговый выпуск: завершить изготовление и передать ящик на контроль ОТК</label></>}
